<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.view');$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare("SELECT d.*,c.company_name,ct.first_name,ct.last_name,ct.email contact_email,u.name owner_name,ps.name_es stage_name,ps.name_pt stage_name_pt,ps.name_en stage_name_en,ps.color FROM deals d JOIN pipeline_stages ps ON ps.id=d.stage_id LEFT JOIN clients c ON c.id=d.client_id LEFT JOIN contacts ct ON ct.id=d.contact_id LEFT JOIN users u ON u.id=d.owner_user_id WHERE d.id=?");$s->execute([$id]);$deal=$s->fetch();if(!$deal){http_response_code(404);exit('Negocio no encontrado.');}$pageTitle=$deal['title'];$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&has_permission('deals.transfer')){verify_csrf();$newOwner=(int)($_POST['owner_user_id']??0);if($newOwner>0){db()->prepare('UPDATE deals SET owner_user_id=? WHERE id=?')->execute([$newOwner,$id]);db()->prepare('UPDATE quotations SET owner_user_id=? WHERE deal_id=?')->execute([$newOwner,$id]);create_in_app_notification($newOwner,'Negocio transferido','Se te asignó el negocio '.$deal['title'],'info','deal_view.php?id='.$id);flash('success','Negocio y cotizaciones relacionadas transferidos.');redirect('deal_view.php?id='.$id);}}$a=db()->prepare('SELECT a.*,u.name assigned_name FROM activities a LEFT JOIN users u ON u.id=a.assigned_to WHERE a.deal_id=? ORDER BY COALESCE(a.due_at,a.created_at) DESC');$a->execute([$id]);$activities=$a->fetchAll();$q=db()->prepare('SELECT * FROM quotations WHERE deal_id=? ORDER BY issue_date DESC,id DESC');$q->execute([$id]);$quotes=$q->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="module-tabs"><a href="deals.php">Pipeline</a><a class="active" href="#">Ficha del negocio</a><?php if(has_permission('activities.manage')):?><a href="activity_form.php?deal_id=<?=$id?>&client_id=<?=(int)$deal['client_id']?>&contact_id=<?=(int)$deal['contact_id']?>">+ Actividad</a><?php endif;?><?php if(has_permission('quotes.create')):?><a href="quotation_form.php?client_id=<?=(int)$deal['client_id']?>&deal_id=<?=$id?>">+ Cotización</a><?php endif;?></div>
<section class="panel"><div class="panel-header"><div><h2><?=e($deal['title'])?></h2><span class="table-sub"><?=e($deal['company_name']?:trim($deal['first_name'].' '.$deal['last_name'])?:'Sin cliente')?> · <?=e(crm_stage_localized(['name_es'=>$deal['stage_name'],'name_pt'=>$deal['stage_name_pt'],'name_en'=>$deal['stage_name_en']]))?></span></div><div class="actions"><?php if($deal['status']==='won'&&$deal['client_id']&&has_permission('services.assign')):?><a class="btn btn-secondary btn-small" href="deal_convert_service.php?id=<?=$id?>">CONVERTIR EN SERVICIO ACTIVO</a><?php endif;?><?php if($deal['status']==='won'&&has_permission('projects.manage')):?><a class="btn btn-secondary btn-small" href="deal_convert_project.php?id=<?=$id?>">CONVERTIR EN PROYECTO</a><?php endif;?><?php if(has_permission('deals.manage')):?><a class="btn btn-primary btn-small" href="deal_form.php?id=<?=$id?>">Editar</a><?php endif;?></div></div><div class="panel-body details-grid"><div class="detail"><small>Valor</small><strong><?=e(format_money($deal['amount'],$deal['currency']))?></strong></div><div class="detail"><small>Probabilidad</small><strong><?=(int)$deal['probability']?>%</strong></div><div class="detail"><small>Pronóstico ponderado</small><strong><?=e(format_money((float)$deal['amount']*((int)$deal['probability']/100),$deal['currency']))?></strong></div><div class="detail"><small>Responsable</small><strong><?=e($deal['owner_name']?:'Sin asignar')?></strong></div><div class="detail"><small>Cierre estimado</small><strong><?=e(format_date($deal['expected_close_date']))?></strong></div><div class="detail"><small>Próxima acción</small><strong><?=e($deal['next_action']?:'—')?></strong></div><?php if($deal['notes']):?><div class="detail" style="grid-column:1/-1"><small>Notas</small><strong style="white-space:pre-wrap"><?=e($deal['notes'])?></strong></div><?php endif;?></div></section>
<?php if(has_permission('deals.transfer')):?><section class="panel"><div class="panel-header"><div><h2>Transferir seguimiento</h2><span class="table-sub">Disponible para administradores globales y usuarios con permiso de transferencia.</span></div></div><form method="post" class="panel-body form-grid"><?=csrf_field()?><label>Nuevo responsable<select name="owner_user_id" required><option value="">Seleccionar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach;?></select></label><div style="align-self:end"><button class="btn btn-secondary">TRANSFERIR NEGOCIO Y COTIZACIONES</button></div></form></section><?php endif;?>
<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Actividad del negocio</h2></div><div class="panel-body activity-timeline"><?php if(!$activities):?><div class="empty">Sin actividades.</div><?php endif;?><?php foreach($activities as$a):?><article class="activity-entry <?=$a['status']==='completed'?'completed':''?>"><div class="activity-entry-icon"><?=crm_icon('activity')?></div><div><h4><?=e($a['subject'])?></h4><p><?=e($a['details'])?></p></div><time><?=e($a['due_at']?(new DateTimeImmutable($a['due_at']))->format('d/m/Y H:i'):'Sin fecha')?></time></article><?php endforeach;?></div></section><aside><section class="panel"><div class="panel-header"><h2>Cotizaciones</h2></div><div class="panel-body metric-list"><?php if(!$quotes):?><div class="empty">Sin cotizaciones relacionadas.</div><?php endif;?><?php foreach($quotes as$q):?><div class="metric-row"><span><a class="table-title" href="quotation_view.php?id=<?=$q['id']?>"><?=e($q['quotation_number'])?></a><small class="table-sub"><?=e(quote_status_label($q['status']))?></small></span><strong><?=e(format_money($q['total'],$q['currency']))?></strong></div><?php endforeach;?></div></section></aside></div>
<?php require __DIR__.'/includes/footer.php';?>
